CREATE TABLE audit_logs(id BINARY(16) PRIMARY KEY,event_id VARCHAR(255) NOT NULL UNIQUE,tenant_id BINARY(16),actor_id BINARY(16) NOT NULL,action VARCHAR(40) NOT NULL,resource_type VARCHAR(100) NOT NULL,resource_id VARCHAR(255) NOT NULL,request_id VARCHAR(255),correlation_id VARCHAR(255),ip_address VARCHAR(64),before_json TEXT,after_json TEXT,occurred_at TIMESTAMP(6) NOT NULL,ingested_at TIMESTAMP(6) NOT NULL,INDEX idx_audit_tenant_time(tenant_id,occurred_at),INDEX idx_audit_resource(resource_type,resource_id));